    //This assume_property doesn't allow SW to update interrupt status (pending, requested, active, paused) . TODO: Remove the constraints after some maturity and either adapt the properties or enforce this in HW by making pending and active SW writable False
    property int_status_not_changed_by_sw;
    @(posedge InterruptController.HCLK_i)
        (1 
	|->
	 ( ~( (InterruptController.comp_Reg_IF.comp_Top_CSC.DefaultInterface_addr >= 16'h0008) && 
	 (InterruptController.comp_Reg_IF.comp_Top_CSC.DefaultInterface_addr < 16'h0018) )));
    endproperty
