    @(posedge InterruptController.HCLK_i)
    disable iff(!InterruptController.HRESET_n_i)
        (( InterruptController.comp_Reg_IF.comp_Top_CSC.BF_active_NMI_Outp_s && 
	  $rose(InterruptController.nmi_ended) ) 
	|->
	  ##1
	 (  $fell(InterruptController.comp_Reg_IF.comp_Top_CSC.BF_pending_NMI_Outp_s) && 
	  $fell(InterruptController.comp_Reg_IF.comp_Top_CSC.BF_active_NMI_Outp_s) && 
	  $fell(InterruptController.comp_Reg_IF.comp_Top_CSC.BF_requested_NMI_Outp_s) ) );
    endproperty
